// === Tab: mySketch ===
let p = new Array(900);
let diagonal;

function setup() {
  for (i = 0; i<p.length; i++) {
    p[i] = new Particle();
    p[i].o = random(1, random(1, width/p[i].n));
  }
  createCanvas(6400, 1800);
  diagonal = int(sqrt)(width*width + height * height)/2;
  background(0);
  noStroke();
  fill(c);
  frameRate(60);
}

let rotation = 0;
function draw() {
  if (!mousePressed)  {
    background(0);
  }

  translate(width/2, height/2);
  rotation-=0.001;
  rotate(rotation);

  for (i = 0; i<p.length; i++) {
    p[i].draw();
    if (p[i].drawDist()>diagonal) {
      p[i] = new Particle();
    }
  }
}

class Particle {
  n;
  r;
  o;
  l;
  constructor() {
    l = 1;
    n = random(1, width/2);
    r = random(0, TWO_PI);
    o = random(1, random(1, width/n));
  }

  function draw() {
    l++;
    pushMatrix();
    rotate(r);
    translate(drawDist(), 0);
		//fill(c, min(1, c));
    fill(242, 169, 0);
    ellipse(0, 0, width/o/8, width/o/8);
    popMatrix();

    o-=0.07;
  }
  drawDist() {
    return atan(n/o)*width/HALF_PI;
  }
}

